-- Schema is currently created from SQLAlchemy models at API startup for the local prototype.
-- This SQL documents the intended PostgreSQL constraints for a migration-managed deployment.
CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(512) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), crypto_salt BYTEA, wrapped_key BYTEA, wrapping_nonce BYTEA, kdf_iterations INTEGER NOT NULL DEFAULT 600000);
CREATE TABLE access_sessions (jti VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES users(id), expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE TABLE files (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(36) NOT NULL REFERENCES users(id), filename VARCHAR(255) NOT NULL, mime_type VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), archived BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE file_versions (id VARCHAR(36) PRIMARY KEY, file_id VARCHAR(36) NOT NULL REFERENCES files(id), version_number INTEGER NOT NULL, object_key VARCHAR(80) NOT NULL UNIQUE, digest CHAR(64) NOT NULL, size INTEGER NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('pending','ready','failed')), tx_hash VARCHAR(80), block_number INTEGER, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(file_id,version_number), UNIQUE(file_id,id));
CREATE TABLE wrapped_file_keys (version_id VARCHAR(36) PRIMARY KEY REFERENCES file_versions(id), owner_id VARCHAR(36) NOT NULL REFERENCES users(id), wrapping_nonce BYTEA NOT NULL, wrapped_dek BYTEA NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_events (id VARCHAR(36) PRIMARY KEY, actor_id VARCHAR(36) REFERENCES users(id), event_type VARCHAR(80) NOT NULL, resource_id VARCHAR(36), outcome VARCHAR(32) NOT NULL, correlation_id VARCHAR(64), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
